--
-- Table structure for table `post_targets`
--

DROP TABLE IF EXISTS `post_targets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `post_targets` (
  `id` int NOT NULL AUTO_INCREMENT,
  `post_id` int NOT NULL,
  `platform` enum('linkedin','youtube','facebook','instagram') COLLATE utf8mb4_unicode_ci NOT NULL,
  `overrides` json DEFAULT NULL,
  `status` enum('pending','uploading','processing','published','failed','skipped') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `progress` tinyint NOT NULL DEFAULT '0',
  `attempts` tinyint NOT NULL DEFAULT '0',
  `next_attempt_at` datetime DEFAULT NULL,
  `locked_at` datetime DEFAULT NULL,
  `external_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `external_url` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `error_raw` json DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `platform_account_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `post_targets_post_platform_uq` (`post_id`,`platform`),
  KEY `post_targets_status_next_attempt` (`status`,`next_attempt_at`),
  KEY `post_targets_platform_account_fk` (`platform_account_id`),
  CONSTRAINT `post_targets_ibfk_1` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `post_targets_platform_account_fk` FOREIGN KEY (`platform_account_id`) REFERENCES `platform_accounts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `post_targets`
--

LOCK TABLES `post_targets` WRITE;
/*!40000 ALTER TABLE `post_targets` DISABLE KEYS */;
INSERT INTO `post_targets` VALUES (5,3,'youtube','{\"privacy\": \"public\"}','published',100,0,NULL,'2026-11-19 07:52:42','pJ7i1Sfkv0c','https://www.youtube.com/shorts/pJ7i1Sfkv0c',NULL,NULL,'2026-11-19 07:52:42','2026-11-19 07:53:22','2026-11-19 07:52:40','2026-11-19 07:53:22',3),(8,6,'linkedin','{\"caption\": \"Today Anthropic goes public under the ticker ANT, and while most people will be watching the share price, I’m thinking about my laptop. A couple of years ago “AI in my workflow” meant autocomplete guessing half a line of code. Now my team at Xavia Solutions ships client work with AI agents built into the pipeline, handling everything from requirement breakdowns and first drafts of code to test cases and proposals. I never planned that, it just slowly became how we work, so a company whose model sits in the middle of my day ringing the Nasdaq bell feels a little personal. Public money should mean better tools and more compute, but it also means more pressure for quarterly growth, so if your business depends on one AI provider, today is a good day to think about a backup plan. I’m not giving investment advice, and I honestly don’t know where ANT closes today. What I do know is that a developer in Karachi now has access to the same model as a team in San Francisco, and that’s never really been true before. The playing field isn’t perfectly fair yet, but it’s a lot flatter. Congrats to the Anthropic team, and now back to building. 🚀 What’s one thing AI genuinely changed in how you work this year? #AI #Anthropic #Claude #SoftwareDevelopment\"}','published',100,0,NULL,'2026-11-19 08:27:52','urn:li:share:7529098110078472194','https://www.linkedin.com/feed/update/urn:li:share:7529098110078472194',NULL,NULL,'2026-11-19 08:27:52','2026-11-19 08:27:54','2026-11-19 08:27:52','2026-11-19 08:27:54',NULL),(9,6,'youtube','{\"privacy\": \"public\"}','skipped',0,0,NULL,NULL,NULL,NULL,'YouTube needs a video (no text or image posts through the API)',NULL,NULL,'2026-11-19 08:27:52','2026-11-19 08:27:52','2026-11-19 08:27:52',NULL),(13,8,'youtube','{\"tags\": [\"APR\", \"credit card\", \"money explained\", \"Penny\'s Dictionary\", \"Why Am I Broke Today\"], \"title\": \"What Is APR? | Penny\'s Dictionary\", \"caption\": \"APR is the yearly cost of a loan, shown as a percentage. The number they hope you won\'t read.\\nA N$10,000 card balance at 30% APR costs about N$3,000 or more a year in interest if you pay nothing off.\\n\\nCompare APRs, not adverts. It\'s the one number that compares loans fairly.\\nWord #3 in Penny\'s Dictionary. One money word at a time, explained by a sarcastic piggy bank.\\nFull episode on the channel.\\nSubscribe for the next word. @whyamibroketoday\\n\\nGeneral information, not financial advice.\\n\\n#apr #creditcard #moneyexplained #shorts #WhyAmIBrokeToday\"}','published',100,0,NULL,'2026-11-19 12:03:30','djqVfUU9kXg','https://www.youtube.com/shorts/djqVfUU9kXg',NULL,NULL,'2026-11-19 12:03:30','2026-11-19 12:03:54','2026-11-19 11:58:07','2026-11-19 12:03:54',7),(14,8,'facebook',NULL,'published',100,0,NULL,'2026-11-19 12:03:30','4791508451135414','https://www.facebook.com/reel/4791508451135414',NULL,NULL,'2026-11-19 12:03:30','2026-11-19 12:04:45','2026-11-19 11:58:07','2026-11-19 12:04:45',14),(15,8,'instagram',NULL,'published',100,0,NULL,'2026-11-19 12:03:35','18101856725643796','https://www.instagram.com/reel/Df7CaAskzIY/',NULL,NULL,'2026-11-19 12:03:36','2026-11-19 12:04:40','2026-11-19 11:58:07','2026-11-19 12:04:40',15),(16,9,'youtube','{\"tags\": [\"infrastructure\", \"government\", \"personal finance\", \"satire\", \"bridge\", \"delays\", \"budget\"], \"title\": \"Why Every Government Project Takes 10 Years\", \"caption\": \"This bridge was promised in 1 year for N$100 million. It took 10 years and N$250 million. Then it led to a cow.\\nFewer than 1 in 10 big projects finish on time and on budget, and the real bill for the delay lands on you.\\n\\nPenny the piggy bank follows one bridge from the promise to the ribbon. Along the way: the poster number that was never real, the cheapest bid that wasn\'t, two foundation stones, a face on the towers, Grandma\'s porch, and why every year late makes the next year more expensive.\\nThen the maths: the overrun cost Sam N$30. The delay cost him N$49,000 and four and a half months in traffic.\\n\\nChapters\\n0:00 Year 10: the bridge opens (onto a field)\\n0:57 Year 1: the promise\\n2:14 Years 2–7: how to build a bridge slowly\\n5:39 Year 9: what the delay really costs you\\n7:07 Who wins, who loses\\n7:54 What you can actually do\\n8:57 Next time: why is everything a subscription?\\n\\nNext episode: Why Is Everything a Subscription Now?\\nSubscribe. It\'s free. For now. @whyamibroketoday\\n\\nSet in the totally fictional country of Nowhereland. Any resemblance to your own country is your problem.\\nGeneral information, not financial advice.\\n\\n#infrastructure #government #personalfinance #satire #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:25:50','2026-11-19 17:25:50',7),(17,9,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:25:50','2026-11-19 17:25:50',14),(18,9,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:25:50','2026-11-19 17:25:50',15),(19,10,'youtube','{\"tags\": [\"infrastructure\", \"government\", \"bridge\", \"satire\", \"shorts\", \"delays\"], \"title\": \"The Bridge Took 10 Years. Look Where It Goes.\", \"caption\": \"Promised in 1 year. Opened after 10, at two and a half times the price. And it connects you to a cow.\\nFull episode on the channel.\\n#infrastructure #government #shorts #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:25:57','2026-11-19 17:25:57',7),(20,10,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:25:57','2026-11-19 17:25:57',14),(21,10,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:25:57','2026-11-19 17:25:57',15),(22,11,'youtube','{\"tags\": [\"deficit\", \"debt\", \"economics\", \"money explained\", \"shorts\", \"personal finance\"], \"title\": \"What Is a Deficit? | Penny\'s Dictionary\", \"caption\": \"A deficit is spending more than you take in. Sam does it every month.\\nEarn N$100, spend N$120: that\'s a N$20 deficit. Add up all the old deficits and you get debt.\\n\\nGovernments do it too, on a bigger scale. Minister Smiles calls it \\\"an investment\\\". In what? Next question.\\nWord #4 in Penny\'s Dictionary. One money word at a time, explained by a sarcastic piggy bank.\\nFull episode on the channel: Where Does Your Tax Money Actually Go?\\nSubscribe for the next word. @whyamibroketoday\\n\\nGeneral information, not financial advice.\\n\\n#deficit #debt #economics #shorts #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:04','2026-11-19 17:26:04',7),(23,11,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:04','2026-11-19 17:26:04',14),(24,11,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:04','2026-11-19 17:26:04',15),(25,12,'youtube','{\"tags\": [\"infrastructure\", \"commute\", \"personal finance\", \"delays\", \"shorts\", \"satire\"], \"title\": \"What a Late Project Really Costs You\", \"caption\": \"The N$150m overrun cost Sam N$30. The 10-year delay cost him N$49,000 and four and a half months in traffic.\\nFull episode on the channel. General information, not financial advice.\\n#infrastructure #commute #shorts #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:09','2026-11-19 17:26:09',7),(26,12,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:09','2026-11-19 17:26:09',14),(27,12,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:09','2026-11-19 17:26:09',15),(28,13,'youtube','{\"tags\": [\"compound interest\", \"savings\", \"money explained\", \"shorts\", \"personal finance\", \"interest\"], \"title\": \"Compound Interest Explained in 30 Seconds | Penny\'s Dictionary\", \"caption\": \"Compound interest is interest on your interest. Great when it\'s yours. Terrible when it\'s a loan\'s.\\nN$1,000 at 10% a year: N$1,100, then N$1,210, then N$1,331. Each year the interest earns interest.\\n\\nSaving? The snowball works for you. Borrowing? It rolls over you.\\nWord #5 in Penny\'s Dictionary. One money word at a time, explained by a sarcastic piggy bank.\\nFull episode on the channel.\\nSubscribe for the next word. @whyamibroketoday\\n\\nGeneral information, not financial advice.\\n\\n#compoundinterest #savings #moneyexplained #shorts #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:16','2026-11-19 17:26:16',7),(29,13,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:16','2026-11-19 17:26:16',14),(30,13,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:16','2026-11-19 17:26:16',15),(31,14,'youtube','{\"tags\": [\"government\", \"satire\", \"infrastructure\", \"podium\", \"shorts\", \"delays\"], \"title\": \"Who Wins When a Project Runs 10 Years Late?\", \"caption\": \"Bronze: the consultants. Silver: the contractor. Gold: three ribbons, two foundation stones, zero roads.\\nFull episode on the channel.\\n#government #satire #shorts #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:22','2026-11-19 17:26:22',7),(32,14,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:22','2026-11-19 17:26:22',14),(33,14,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:22','2026-11-19 17:26:22',15),(34,15,'youtube','{\"tags\": [\"government\", \"election\", \"satire\", \"bridge\", \"shorts\", \"infrastructure\"], \"title\": \"Why Does the Same Bridge Get Two Foundation Stones?\", \"caption\": \"Election year: lay the foundation stone. Again. Then make the bridge bigger, with your face on it.\\nFull episode on the channel.\\n#government #election #shorts #WhyAmIBrokeToday\", \"privacy\": \"private\"}','pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:28','2026-11-19 17:26:28',7),(35,15,'facebook',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:28','2026-11-19 17:26:28',14),(36,15,'instagram',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-19 17:26:28','2026-11-19 17:26:28',15),(37,16,'linkedin',NULL,'published',100,0,NULL,'2026-11-21 05:00:00','urn:li:share:7529770564299923456','https://www.linkedin.com/feed/update/urn:li:share:7529770564299923456',NULL,NULL,'2026-11-21 05:00:00','2026-11-21 05:00:01','2026-11-20 14:56:08','2026-11-21 05:00:01',11),(38,17,'linkedin',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 14:56:08','2026-11-20 14:56:08',11),(39,18,'linkedin',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 14:56:08','2026-11-20 14:56:08',11),(40,19,'linkedin',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 14:56:08','2026-11-20 14:56:08',11),(41,20,'linkedin',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 14:56:08','2026-11-20 14:56:08',11),(42,21,'linkedin',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 14:56:08','2026-11-20 14:56:08',11),(43,22,'linkedin',NULL,'pending',0,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-11-20 18:11:57','2026-11-20 18:11:57',11);
